/* Product rules contain no guessed institutional requirements. */
const ProductCore=(()=>{
 const categories=['Academic interests','Personal strengths','Problem solving','Creativity','Technical interests','Communication','Leadership','Independent / collaborative work','Working environment','Career values','Work-life balance','Long-term ambitions'];
 const questions=[
 ['A school exhibition needs a new attraction. What would you make?',['A working device','A story about people','An interactive installation','A student-run venture'],['build','people','create','lead']],
 ['A friend asks for your strongest contribution. You offer…',['Finding the logic','Listening carefully','Imagining alternatives','Getting everyone organized'],['logic','people','create','lead']],
 ['A project fails its first test. Your next move?',['Measure what failed','Ask who was affected','Try a different design','Study earlier experiments'],['logic','people','create','research']],
 ['An empty room becomes a student space. You focus on…',['How things function','Making everyone welcome','How the room feels','How to run it sustainably'],['build','people','create','lead']],
 ['You can shadow someone for a day. Choose…',['An electronics engineer','A community health worker','A designer','A field scientist'],['build','people','create','research']],
 ['A complicated idea needs explaining. You would rather…',['Build a demonstration','Talk it through one to one','Draw a visual story','Present a clear action plan'],['build','people','create','lead']],
 ['Your team has too many ideas. How do you help?',['Test the most workable one','Make sure quieter voices are heard','Combine ideas into a new direction','Agree priorities and assign tasks'],['logic','people','create','lead']],
 ['Which project setup sounds better?',['Focused solo time solving a system','Pairing with someone and sharing feedback','Owning a creative piece within a team','Coordinating several people’s work'],['logic','people','create','lead']],
 ['Which workspace would you explore first?',['A prototyping workshop','A community support center','A design studio','An outdoor research station'],['build','people','create','research']],
 ['Which outcome would make a project feel worthwhile?',['A tool that solves a real problem','Someone’s life becoming easier','An idea people see differently','Evidence that changes a decision'],['build','people','create','research']],
 ['A deadline is tight. Which trade-off feels most comfortable?',['A focused technical sprint followed by recovery','Predictable hours with steady collaboration','Flexible hours with creative autonomy','A varied schedule with leadership responsibility'],['logic','people','create','lead']],
 ['Ten years from now, you would like to have…',['Built useful systems','Supported a healthier community','Created a recognizable body of work','Led a meaningful organization'],['build','people','create','lead']],
 ['Which optional class would you try?',['Coding and mathematics','Human behavior','Visual storytelling','Environmental field methods'],['logic','people','create','research']],
 ['At a science fair you stop longest at…',['A robot adapting to obstacles','A study of how people learn','A playful interactive exhibit','A water-quality investigation'],['build','people','create','research']],
 ['You receive messy survey data. What interests you?',['Finding patterns','Understanding individual experiences','Showing the findings visually','Deciding what action to take'],['logic','people','create','lead']],
 ['A community garden needs help. You choose…',['Build an irrigation sensor','Talk with local residents','Design signs and the layout','Compare soil and growing conditions'],['build','people','create','research']],
 ['Which kind of feedback would you ask for?',['Does my solution work reliably?','Did I understand people’s needs?','Does this feel clear and original?','Did the team reach its goal?'],['logic','people','create','lead']],
 ['You can learn a skill for a month. Pick…',['Making simple circuits','Interviewing and counseling basics','Animation and prototyping','Planning a small event'],['build','people','create','lead']],
 ['A club is losing members. Your first question is…',['Which activity formats work best?','What do members need?','How could the experience change?','What is our shared purpose?'],['research','people','create','lead']],
 ['A device stops working. You are most curious about…',['The faulty part','How it disrupted someone’s day','How a redesign could prevent confusion','The pattern across similar failures'],['build','people','create','research']],
 ['Which reading would you choose for a long train ride?',['How complex systems work','Why people behave differently','How creative work develops','How a team built a new organization'],['logic','people','create','lead']],
 ['Your school offers a volunteer project. You choose…',['Repair useful objects','Support peers','Make accessible learning materials','Organize a donation drive'],['build','people','create','lead']],
 ['A claim sounds surprising. You want to…',['Check the reasoning','Hear from the people involved','Explore other interpretations','Design a careful investigation'],['logic','people','create','research']],
 ['Which challenge would you happily revisit?',['Improving a prototype','Helping someone make progress','Refining an original design','Investigating an unanswered question'],['build','people','create','research']],
 ['A team must choose a direction with limited time. You prefer…',['A small experiment','A conversation with affected people','A quick set of sketches','A decision framework and milestones'],['research','people','create','lead']],
 ['What makes a collaborative project satisfying?',['Connecting technical pieces','Building mutual trust','Bringing different ideas together','Keeping everyone moving toward a goal'],['build','people','create','lead']],
 ['Which problem could hold your attention for weeks?',['A difficult algorithm','A barrier to community wellbeing','A confusing everyday product','A change in the natural environment'],['logic','people','create','research']],
 ['You have a small project budget. Spend it on…',['Components and tools','Conversations and user visits','Materials for prototypes','Measuring and testing equipment'],['build','people','create','research']],
 ['Which responsibility feels energizing?',['Making a system dependable','Supporting another person','Setting a creative direction','Helping a group make decisions'],['logic','people','create','lead']],
 ['You would rather present your learning through…',['A working example','A conversation','A portfolio','A research report'],['build','people','create','research']],
 ['After a difficult week, what restores your motivation?',['Solving a small puzzle on my own','Sharing experiences with others','Making something just for expression','Reading about a question I care about'],['logic','people','create','research']],
 ['Which next step feels most like you?',['Build, test, improve','Listen, understand, support','Imagine, create, refine','Plan, organize, lead'],['build','people','create','lead']]
 ].map((q,i)=>({id:'q'+(i+1),category:categories[i%categories.length],prompt:q[0],choices:q[1],tags:q[2]}));
 function rank(answers,majors){const tally={};for(const tag of answers)if(['build','logic','people','create','research','lead'].includes(tag))tally[tag]=(tally[tag]||0)+1;return majors.map((m,i)=>({...m,weight:m.tags.reduce((n,t)=>n+(tally[t]||0),0),order:i})).sort((a,b)=>b.weight-a.weight||a.order-b.order)}
 function quizDraft(raw){if(!raw||![12,32].includes(raw.length)||!Array.isArray(raw.answers))return null;const a=raw.answers.slice(0,raw.length).filter((tag,i)=>questions[i]?.tags.includes(tag));return{length:raw.length,answers:a,index:Math.max(0,Math.min(Number.isInteger(raw.index)?raw.index:a.length,a.length,raw.length-1))}}
 const institutions=[
 {name:'University of Washington Seattle',location:'Seattle',kind:'University',calendar:'Quarter',coverage:'Two Bellevue math credit mappings; no complete degree audit',url:'https://www.washington.edu/',admissions:'https://admit.washington.edu/apply/',programs:'https://admit.washington.edu/academics/majors/'},
 {name:'University of Washington Bothell',location:'Bothell',kind:'University',calendar:'Quarter',coverage:'EE foundation/core roadmap; selected Bellevue mappings',url:'https://www.uwb.edu/',admissions:'https://www.uwb.edu/admissions',programs:'https://www.uwb.edu/stem/undergraduate/majors/electrical'},
 {name:'University of Washington Tacoma',location:'Tacoma',kind:'University',calendar:'Quarter',coverage:'Research links only; course mappings not verified',url:'https://www.tacoma.uw.edu/',admissions:'https://www.tacoma.uw.edu/admissions',programs:'https://www.tacoma.uw.edu/'},
 {name:'Washington State University',location:'Pullman / multiple campuses',kind:'University',calendar:'Semester',coverage:'Research links only; semester degree rules not loaded',url:'https://wsu.edu/',admissions:'https://admission.wsu.edu/',programs:'https://wsu.edu/'},
 {name:'Bellevue College',location:'Bellevue',kind:'Community college',calendar:'Quarter',coverage:'Selected mappings to UW Seattle and UWB',url:'https://www.bellevuecollege.edu/',admissions:'https://www.bellevuecollege.edu/admissions/',programs:'https://www.bellevuecollege.edu/'},
 {name:'Cascadia College',location:'Bothell',kind:'Community college',calendar:'Quarter',coverage:'Research links only; course mappings not verified',url:'https://www.cascadia.edu/',admissions:'https://www.cascadia.edu/',programs:'https://www.cascadia.edu/'},
 {name:'Seattle Colleges',location:'Seattle',kind:'Community college',calendar:'Quarter',coverage:'Research links only; campus-specific mappings not verified',url:'https://www.seattlecolleges.edu/',admissions:'https://www.seattlecolleges.edu/',programs:'https://www.seattlecolleges.edu/'}
 ];
 function terms(profile={},index=0){const semester=profile.calendar==='Semester';const all=semester?['Fall','Spring',...(profile.summer?['Summer']:[])]:['Fall','Winter','Spring',...(profile.summer?['Summer']:[])];const start=all.indexOf(profile.startTerm||'Winter'),offset=Math.max(0,start)+index;return{season:all[offset%all.length],year:Number(profile.startYear)||2027,offsetYear:Array.from({length:index},(_,i)=>{const months={Fall:9,Winter:1,Spring:4,Summer:7};return months[all[(Math.max(0,start)+i+1)%all.length]]<months[all[(Math.max(0,start)+i)%all.length]]?1:0}).reduce((a,b)=>a+b,0)}}
 function termName(profile,index){const t=terms(profile,index);return t.season+' '+(t.year+t.offsetYear)}
 function validatePlan(courses,done=[],profile={},limit=15){const errors=[],seen=new Set(),complete=new Set(done);for(const c of courses){if(seen.has(c.code))errors.push('Duplicate planned course: '+c.code);seen.add(c.code);if(!Number.isInteger(c.term)||c.term<0||c.term>47)errors.push(c.code+': choose a term from 1 to 48.');for(const pre of c.prereqs||[])if(!complete.has(pre)&&!courses.some(p=>p.code===pre&&p.term<c.term))errors.push(c.code+' needs '+pre+' in an earlier term.');for(const co of c.coreqs||[])if(!complete.has(co)&&!courses.some(p=>p.code===co&&p.term<=c.term))errors.push(c.code+' needs '+co+' no later than the same term.');if(c.seasons&&!c.seasons.includes(terms(profile,c.term).season.replace('Fall','Autumn')))errors.push(c.code+' is restricted to '+c.seasons.join(' / ')+'.');if(profile.calendar==='Semester'&&c.institution!=='Washington State University'&&c.source)errors.push('Quarter-based institutional rules cannot be used for a semester plan.');}
 for(const term of new Set(courses.map(c=>c.term))){const list=courses.filter(c=>c.term===term);if(list.reduce((n,c)=>n+Number(c.credits),0)>limit)errors.push('Term '+(term+1)+' exceeds the '+limit+'-credit cap.');if(+profile.maxCourses&&list.length>+profile.maxCourses)errors.push('Term '+(term+1)+' exceeds your '+profile.maxCourses+'-course preference.');}return[...new Set(errors)]}
 function signature(state,mode){return JSON.stringify({courses:(state.courses||[]).map(c=>[c.code,c.grade,c.completed,c.status,c.term,c.institution,c.credits]),profile:state.profile,providers:state.courseProviders,electives:state.selectedElectives,mode})}
 function diff(base,variant){const b=new Map(base.courses.map(c=>[c.code,c])),v=new Map(variant.courses.map(c=>[c.code,c]));return{added:[...v.keys()].filter(k=>!b.has(k)),removed:[...b.keys()].filter(k=>!v.has(k)),moved:[...v.keys()].filter(k=>b.has(k)&&(b.get(k).term!==v.get(k).term||b.get(k).institution!==v.get(k).institution)),baseTerms:base.courses.length?Math.max(...base.courses.map(c=>c.term))+1:0,terms:variant.courses.length?Math.max(...variant.courses.map(c=>c.term))+1:0,conflicts:variant.errors||variant.blocked||[],supported:variant.supported}}
 function mappings(engine,academic){return[{id:'uwb-java-series',sourceInstitution:academic.BC,sourceCourse:'CS 210 + CS 211 (complete series)',destinationInstitution:academic.UWB,destinationCourse:'CSS/CSSSKL 142 + 143',catalogYear:null,effective:'Confirm catalog year and course term',url:academic.sources.stem,lastVerified:academic.checked,status:'Published series guidance',applicability:'Programming course-content guidance',restrictions:'Full Bellevue series required; mixed-school single-course credit needs advisor confirmation'},...engine.equivalencies.map((r,i)=>({id:'uws-'+i,sourceInstitution:r.source,sourceCourse:r.code,destinationInstitution:r.target,destinationCourse:r.credit,catalogYear:null,effective:r.effective,url:r.url,lastVerified:r.checked,status:'Published mapping; catalog-year confirmation needed',applicability:'Course credit; major applicability not verified',restrictions:r.type})),...academic.groups.filter(g=>g.bc.length&&g.uw.length).map(g=>({id:'uwb-'+g.id,sourceInstitution:academic.BC,sourceCourse:g.bc.join(' / '),destinationInstitution:academic.UWB,destinationCourse:g.uw.join(' / '),catalogYear:null,effective:'Confirm course term and catalog year',url:g.source,lastVerified:academic.checked,status:'Published guidance; record-specific confirmation needed',applicability:'Course-content guidance; requirement and grade review separate',restrictions:g.id.startsWith('phys')?'Bellevue local PHYS numbering; lab credit reviewed separately':'Alternative courses are not interchangeable completed credits'}))]}
 function safeURL(raw){try{const u=new URL(raw);return u.protocol==='https:'?u.href:''}catch{return''}}
 return{categories,questions,rank,quizDraft,institutions,terms,termName,validatePlan,signature,diff,mappings,safeURL};
})();
if(typeof module!=='undefined')module.exports=ProductCore;
